# POST /api/sheets/{sheetId}/claims/{claimId}/reassign — move a claim to another person on the sheet
# (body {to, user}, `to` the person's id). A role the sheet's permission matrix
# allows (perm-reassign; by default a steward) moves a claim, and only a DRAFT, OPEN or
# PENDING one that is not a correction; it keeps its number and date, loses any figure a statement
# bound it to, and is listed as its new person's newest claim. Refused (400) when the matrix does not
# allow the user's role, the claim is SETTLED or VOID, the claim or the person is not on the sheet, the person is
# the claim's own, the claim's due-by falls in a closed period, or its date is after the date the person is
# retired from; nothing is stored then. A stored move is recorded in the audit file as CLAIM_REASSIGNED.
validate:
  class: net.officefloor.hq.app.claim.ValidateReassign
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkReassign
checkReassign:
  class: net.officefloor.hq.app.claim.CheckReassign
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyReassign
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimReassigned
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/bulk-settle — settle the selected claims together (body {claimIds, user}).
# Each selected claim is settled in list order — people in the order they were added, a person's
# claims newest first — by exactly the rules of a single settle by the user, and recorded as a single
# settle is (CLAIM_SETTLED, or CLAIM_PENDING for a clerk above the clerk limit, which counts as
# settled); each that a single settle would refuse is refused and left as it is. Answers
# {settled, refused}. Refused (400) only when no claim is selected.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkSettle
  next: settle
settle:
  class: net.officefloor.hq.app.claim.SettleClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkSettle
  govern: [ transaction ]
