package net.officefloor.hq.app.claim;

/** Body of a claim's move to another person, as sent: the id of the person to move it to and who moves it. */
public record ReassignRequest(String to, String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateReassign {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ReassignRequest request, Out<ReassignInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String to = request == null || request.to() == null ? "" : request.to().trim();
        if (to.isEmpty()) {
            throw new InvalidSheetException("Choose the person to move the claim to");
        }
        try {
            body.set(new ReassignInput(Long.parseLong(to), request.user()));
        } catch (NumberFormatException e) {
            throw new InvalidSheetException("No such person: " + to);
        }
    }
}
package net.officefloor.hq.app.claim;

/** A validated move of a claim to the person {@code to} (their id), by {@code user}. */
public record ReassignInput(long to, String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Refuses a claim's move unless a role the sheet's permission matrix allows to reassign (by
 *  default a steward) moves a DRAFT, OPEN or PENDING claim that is not a
 *  correction to another person on the sheet, who is not retired from before the claim's date. */
public class CheckReassign {
    public void check(@Val ReassignInput input, @Val Claim claim, RoleStore roles, PersonStore people,
            SettingStore settings, Out<Reassignment> reassignment) throws InvalidSheetException {
        Role role = roles.find(claim.getSheetId(), input.user());
        if (!settings.allows(claim.getSheetId(), "reassign", role)) {
            throw new InvalidSheetException("A " + role.shown() + " may not move a claim");
        }
        if (!claim.getStatus().canMove()) {
            throw new InvalidSheetException("A " + claim.getStatus() + " claim cannot move");
        }
        if (claim.isCorrection()) {
            throw new InvalidSheetException("A correction stays with the claim it corrects");
        }
        Person from = people.find(claim.getSheetId(), claim.getPersonId());
        Person to = people.find(claim.getSheetId(), input.to());
        if (to == null) {
            throw new InvalidSheetException("No such person: " + input.to());
        }
        if (to.getId() == claim.getPersonId()) {
            throw new InvalidSheetException("The claim is already " + to.getName() + "'s");
        }
        Retirement.refuseClaimDate(to, claim.getDate());
        reassignment.set(new Reassignment(from, to));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to its new person: it keeps its number and date, loses any figure a statement
 *  bound it to, and is listed as their newest claim. */
public class ApplyReassign {
    public void apply(@Val Claim claim, @Val Reassignment reassignment, ClaimStore store) throws InvalidSheetException {
        if (!store.reassign(claim, reassignment.to().getId())) {
            throw new InvalidSheetException("The claim has moved on");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;

/** A claim's move from the person it was with to the person it goes to. */
public record Reassignment(Person from, Person to) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a stored move: CLAIM_REASSIGNED sheet=<id> by=<user> person=<new name> amount=<0.00>
 *  date=<yyyy-mm-dd>, then number=<n> when the claim has one, then from=<old name> to=<new name>. */
public class AuditClaimReassigned {
    public void audit(@Val ReassignInput input, @Val Claim claim, @Val Reassignment reassignment, @Val Rollup before,
            Audit audit, RollupService rollups) {
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_REASSIGNED sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + reassignment.to().getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber())
                + " from=" + reassignment.from().getName() + " to=" + reassignment.to().getName());
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}

